import 'package:bloc/bloc.dart';import 'package:meta/meta.dart';import '../../data/entities/all_categories_entities.dart';import '../../data/entities/category_data_entities.dart';import '../../domain/UseCase/all_categories_use_case.dart';import '../../domain/UseCase/preview_categories_use_case.dart';class ExploreCubit extends Cubit<ExploreStateClass> {  ExploreCubit(this.allCategoriesUseCase, this.previewCategoriesUseCase)      : super(ExploreStateClass());  final AllCategoriesUseCase allCategoriesUseCase;  final PreviewCategoriesUseCase previewCategoriesUseCase;  int index = 0;  final Map<int, List<CategoryDataPreviewEntities>> _cachedCategories = {};  Future<void> init() async {    await getCategories();    if (state.categories.isNotEmpty) {      await previewCategories(id: state.categories.first.id);    }  }  Future<void> getCategories() async {    final response = await allCategoriesUseCase.call();    response.fold(      (failure) {},      (data) {        emit(state.copyWith(categories: data));      },    );  }  Future<void> previewCategories({required int id}) async {    if (_cachedCategories.containsKey(id)) {      emit(state.copyWith(categoryDataPreview: _cachedCategories[id]!));      return;    }    emit(state.copyWith(categoryDataPreview: []));    final response = await previewCategoriesUseCase.call(id: id);    response.fold(      (failure) {},      (data) {        _cachedCategories[id] = data;        emit(state.copyWith(categoryDataPreview: data));      },    );  }}@immutableclass ExploreStateClass {  final List<AllCategoriesEntities> categories;  final List<AllCategoriesEntities> subCategories;  final List<CategoryDataPreviewEntities> categoryDataPreview;  const ExploreStateClass({    this.categories = const [],    this.subCategories = const [],    this.categoryDataPreview = const [],  });  ExploreStateClass copyWith({    List<AllCategoriesEntities>? categories,    List<AllCategoriesEntities>? subCategories,    List<CategoryDataPreviewEntities>? categoryDataPreview,  }) {    return ExploreStateClass(      categories: categories ?? this.categories,      categoryDataPreview: categoryDataPreview ?? this.categoryDataPreview,      subCategories: subCategories ?? this.subCategories,    );  }}